def merge_routes(base, override):
    """合并网关路由配置。"""
    result = dict(base)
    for key, value in override.items():
        if value is None:
            continue
        if isinstance(value, dict) and isinstance(result.get(key), dict):
            result[key] = merge_routes(result[key], value)
        else:
            result[key] = value
    return result

verification_tests:
from target import merge_routes


def test_list_items_are_merged_by_index():
    result = merge_routes(
        {"routes": [{"path": "/a", "timeout": 10}, {"path": "/b"}]},
        {"routes": [{"timeout": 99}]},
    )
    assert result == {"routes": [{"path": "/a", "timeout": 99}, {"path": "/b"}]}


def test_longer_base_list_is_preserved():
    result = merge_routes({"routes": [{"path": "/a"}, {"path": "/b"}]}, {"routes": []})
    assert result == {"routes": [{"path": "/a"}, {"path": "/b"}]}


def test_scalar_override_wins():
    assert merge_routes({"a": 1}, {"a": 2}) == {"a": 2}
